begin;
do $$
declare owner_id uuid;staff_id uuid:=gen_random_uuid();a text:='qa_area_'||replace(gen_random_uuid()::text,'-','');b text:='qa_area_'||replace(gen_random_uuid()::text,'-','');email text;result jsonb;history_id uuid:=gen_random_uuid();area_id text;
begin
 select u.id into owner_id from auth.users u where lower(u.email)='dancu1213t@gmail.com';email:='qa-staff-'||staff_id||'@example.com';
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,aud,role) values(staff_id,email,now(),jsonb_build_object('swift_staff_created_by',owner_id),'{}','authenticated','authenticated');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 insert into public.stores(category,is_open) values(a,'yes'),(b,'yes');
 insert into public.swift_store_registry(category,name,business_type,zone_id,status,created_by) values(a,'QA Other Area','Food','orange-walk','live',owner_id),(b,'QA Assigned Area','Cafes','belize-city','live',owner_id);
 insert into public.merchant_storefronts(category,auto_close) values(a,false),(b,false);
 insert into public.products(id,name,category,price,active) values(a,'Hidden other-area product',a,10,'yes'),(b,'Assigned area product',b,15,'yes');
 insert into public.customer_order_tracking(id,access_token,snapshot,phase,zone_id) values(history_id,gen_random_uuid(),jsonb_build_object('customer_name','QA history','test_store',b,'items','[]'::jsonb,'pickup_service',true,'pickup_location','17.504,-88.196'), 'delivered','belize-city');
 perform public.swift_admin_staff_account(email,staff_id,'belize-city',true);
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 if public.is_admin() then raise exception 'Scoped user received global admin role';end if;
 if public.swift_admin_portal_access()->>'zone_id'<>'belize-city' then raise exception 'Assigned area missing';end if;
 result:=public.swift_admin_workspace();
 if exists(select 1 from jsonb_array_elements(result->'stores') x where x->>'zone_id'<>'belize-city') then raise exception 'Workspace leaked another area';end if;
 begin perform public.swift_admin_workspace('orange-walk');raise exception 'Other area was allowed';exception when insufficient_privilege then null;end;
 begin perform public.swift_admin_portal_snapshot('orange-walk');raise exception 'Tracking leaked another area';exception when insufficient_privilege then null;end;
 begin perform public.swift_admin_catalogue('belize-city',a);raise exception 'Catalogue leaked another store';exception when insufficient_privilege then null;end;
 begin perform public.swift_admin_product_save(a,jsonb_build_object('name','Bad edit','category',a,'price',1));raise exception 'Cross-area edit allowed';exception when insufficient_privilege then null;end;
 perform public.swift_admin_product_save(b,jsonb_build_object('name','Assigned area edit','category',b,'price',16));
 perform public.swift_admin_banner('save',b,null,jsonb_build_object('image_data','data:image/webp;base64,'||repeat('A',40),'published',false));
 perform public.swift_admin_store_details(b,jsonb_build_object('latitude',17.504,'longitude',-88.196));
 begin perform public.swift_admin_delete_store(b);raise exception 'Scoped delete allowed';exception when insufficient_privilege then null;end;
 begin perform public.swift_admin_session();raise exception 'Global legacy session allowed';exception when insufficient_privilege then null;end;
 begin perform public.swift_admin_area_activate('corozal',true);raise exception 'Area activation allowed for coadmin';exception when insufficient_privilege then null;end;
 if has_function_privilege('authenticated','public.swift_admin_portal_snapshot_internal(text)','execute') then raise exception 'Internal global query is exposed';end if;
 if jsonb_array_length(public.swift_admin_catalogue('belize-city',b)->'items')<>1 then raise exception 'Scoped catalogue failed';end if;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 result:=public.swift_admin_delete_store(b);if (result->>'products')::int<>1 then raise exception 'Deletion preview incorrect';end if;
 begin perform public.swift_admin_delete_store(b,'wrong');raise exception 'Deletion confirmation missing';exception when raise_exception then if sqlerrm='Deletion confirmation missing' then raise;end if;end;
 perform public.swift_admin_delete_store(b,'QA Assigned Area');
 if exists(select 1 from public.products where category=b) or exists(select 1 from public.swift_store_registry where category=b) then raise exception 'Store data not deleted';end if;
 if not exists(select 1 from public.customer_order_tracking where id=history_id) then raise exception 'Historical order was deleted';end if;
 if not exists(select 1 from public.products where id=a) then raise exception 'Other store was changed';end if;
 perform public.swift_admin_staff_account(email,staff_id,'belize-city',false);
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 begin perform public.swift_admin_portal_access();raise exception 'Disabled coadmin retained access';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 area_id:=public.swift_admin_area_create('QA Rollback New Area','BZ-CY',jsonb_build_object('latitude',17.25,'longitude',-88.767,'radius_km',2,'fee_cents',500));
 if not exists(select 1 from public.swift_service_zones where id=area_id and active and rates_approved and coverage is not null) then raise exception 'New area failed to activate';end if;
end $$;
select 'PASS: assigned-area reads/writes, global/other-area denial, no global admin role, revocation, reviewed deletion with history preserved, and new-area activation. All fixtures rolled back.' result;
